// Postprocessor against rk3588_common.model_io.postprocess_raw. The data in postprocess_fixture.h
// (generated by tools/generate/make_postprocess_fixture.py) is three real INT8 board outputs and
// the detections that the Python code returns for them, at two letterbox mappings, at the
// deployment confidence threshold 0.25. Exit code 0 when every case matches.
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdlib>
#include <optional>
#include <vector>

#include "logger.h"
#include "postprocess.h"
#include "postprocess_fixture.h"

namespace {
constexpr std::size_t classCount{5};
constexpr std::size_t anchorCount{8400};
constexpr std::size_t aboveMaxAnchors{30'001};
constexpr int modelSize{640};
constexpr std::size_t boxChannels{4};
constexpr float boxTolerance{1e-3F}; // pixels
constexpr float scoreTolerance{1e-6F};

// The dense [9][8400] output of one fixture image: zero except for the stored anchors.
std::vector<float> denseOutput(std::size_t image) {
    std::size_t first{0};
    for (std::size_t previous{0}; previous < image; ++previous) {
        first += fixture::rowCounts.at(previous);
    }
    std::vector<float> output((boxChannels + classCount) * anchorCount, 0.0F);
    for (std::size_t row{first}; row < first + fixture::rowCounts.at(image); ++row) {
        const fixture::Row& stored{fixture::rows.at(row)};
        for (std::size_t channel{0}; channel < stored.values.size(); ++channel) {
            output.at(channel * anchorCount + static_cast<std::size_t>(stored.anchor)) =
                stored.values.at(channel);
        }
    }
    return output;
}

bool sameBox(const Detection& got, const fixture::Box& want) {
    return got.classId == want.classId && std::fabs(got.left - want.left) <= boxTolerance &&
           std::fabs(got.top - want.top) <= boxTolerance &&
           std::fabs(got.right - want.right) <= boxTolerance &&
           std::fabs(got.bottom - want.bottom) <= boxTolerance &&
           std::fabs(got.confidence - want.confidence) <= scoreTolerance;
}

bool checkCase(std::size_t index, const Logger& log) {
    const fixture::Case& item{fixture::cases.at(index)};
    const fixture::Mapping& mapped{fixture::mappings.at(item.mapping)};
    PostprocessConfig config{};
    config.classCount = classCount;
    config.anchorCount = anchorCount;
    config.modelSize = modelSize;
    config.normalizedBoxes = true;
    config.confThreshold = item.confThreshold;
    std::optional<Postprocessor> post{Postprocessor::create(config, log)};
    if (!post) {
        return false;
    }
    const SourceMapping mapping{mapped.gain, mapped.left, mapped.top, mapped.width, mapped.height};
    if (!post->process(denseOutput(item.image), mapping)) {
        return false;
    }
    const std::vector<Detection>& got{post->detections()};
    if (got.size() != item.boxCount) {
        log.error("case ", index, ": ", got.size(), " detections, expected ", item.boxCount);
        return false;
    }
    std::size_t wrong{0};
    for (std::size_t slot{0}; slot < got.size(); ++slot) {
        if (!sameBox(got.at(slot), fixture::boxes.at(item.firstBox + slot))) {
            ++wrong;
            const Detection& det{got.at(slot)};
            const fixture::Box& want{fixture::boxes.at(item.firstBox + slot)};
            log.error("case ", index, " detection ", slot, " got ", det.left, " ", det.top, " ",
                      det.right, " ", det.bottom, " ", det.confidence, " ", det.classId,
                      ", expected ", want.left, " ", want.top, " ", want.right, " ", want.bottom,
                      " ", want.confidence, " ", want.classId);
        }
    }
    return wrong == 0;
}

bool checkRejects(const Logger& log) {
    PostprocessConfig config{};
    config.classCount = classCount;
    config.anchorCount = anchorCount;
    config.modelSize = modelSize;
    PostprocessConfig noClasses{config};
    noClasses.classCount = 0;
    PostprocessConfig tooManyAnchors{config};
    tooManyAnchors.anchorCount = aboveMaxAnchors;
    std::optional<Postprocessor> post{Postprocessor::create(config, log)};
    const std::vector<float> shortOutput(10, 0.0F);
    const bool configsRejected{!Postprocessor::create(noClasses, log) &&
                               !Postprocessor::create(tooManyAnchors, log)};
    const bool shapeRejected{post && !post->process(shortOutput, SourceMapping{}) &&
                             post->detections().empty()};
    if (!configsRejected || !shapeRejected) {
        log.error("a bad configuration or output size was accepted");
    }
    return configsRejected && shapeRejected;
}
} // namespace

int main() {
    const Logger log{"TEST_POST", LogLevel::Debug};
    bool passed{checkRejects(log)};
    for (std::size_t index{0}; index < fixture::cases.size(); ++index) {
        passed = checkCase(index, log) && passed;
    }
    if (passed) {
        log.info("PASS ", fixture::cases.size(), " cases");
    } else {
        log.error("FAIL");
    }
    return passed ? EXIT_SUCCESS : EXIT_FAILURE;
}
